-- 0215: the same defect as 0213, in every state — Mountain Project copies of areas we already
-- had, folded back into ours. Generated by .scratch-style classification; the per-pair plan is
-- audits/import-copy-areas-2026-09-25/plan-proposed.json, the full row snapshot is rollback.json beside it.
--
-- Approved directly: "yes apply 0210, and fix the importer and other states too".
--
-- WHAT A PAIR IS. Two areas in one state whose names match (catalog_key, 0214), under different
-- parents, within 3 km, both holding routes — 475 such pairs. Only 224 are acted on here:
--
--   COPY    = the side holding ONLY import rows (ice/mixed/aid, a per-scale grade number, no
--             description, no FA): what import-mp-grades.mjs --create-areas builds when it cannot
--             find an area by name under the parent it has reached. Almost always the id with the
--             counter (`_2`, `_8`), and very often under a copy of the keeper's PARENT too
--             (ut_indian_creek_2, ca_mount_morrison, nh_rumney_ice_climbs).
--   KEEPER  = the other side, which holds established routes. NOT "the richer row": outside WA
--             the OpenBeta originals are as thin as the import rows (12 vs 15 columns), so richness
--             would have kept the copy.
--
--   acted on (224): the leaf names match STRICTLY (ignoring "The", "Mt."/"Mount", punctuation),
--     the copy holds no sub-areas, the keeper holds routes directly, and no copy is paired twice.
--   NOT acted on, listed in plan.json / the PR: 200 pairs where BOTH sides hold established routes
--     (older duplicates, not this import's), 26 whose keeper has sub-areas (a route cannot land
--     there), 12 copies with sub-areas, 8 whose names differ ("Quandary Peak" vs "Quandary Ice
--     Crag" — the loose key matched two real places), and 5 chained/ambiguous.
--
-- PER ROUTE on the copy:
--   - same climb on the keeper (STRICT name match): the keeper gains ice/mixed/aid_grade_num if it
--     lacked them (nothing else — 0213's reasons), and the copy row is deleted.
--   - otherwise it MOVES into the keeper area. A loose-only match ("Ice Spray" vs "Spray") moves
--     too: two similar rows side by side lose nothing; a wrong delete loses a climb.
--
-- Nothing a climber made points at any of it: all 13 referencing tables counted 0 for the deleted
-- routes and the copy areas.


-- A COPY PARENT this leaves empty (97 of them, e.g. ak_boy_scout_rocks_2) is NOT deleted: some are
-- real areas ("The Sawtooth Range", "Boston Basin Peaks") that only held the copy. They are listed in
-- audits/import-copy-areas-2026-09-25/empty-parents.json to be read, not swept. Every guard below
-- re-checks the live row, so a plan that has gone stale does nothing rather than the wrong thing.

begin;

create temp table m_dup(copy text primary key, keep text not null, keep_area text not null) on commit drop;

create temp table m_move(id text primary key, from_area text not null, to_area text not null) on commit drop;

create temp table m_copy(id text primary key) on commit drop;

-- Areas whose route_count this can change: every ancestor of a keeper or a copy, taken now.
create temp table m_recount on commit drop as
  select distinct a.id from areas a, areas t
   where t.id in (select keep_area from m_dup union select to_area from m_move union select id from m_copy)
     and a.path @> t.path;

-- 1. the keeper gains the import's per-scale grade numbers it lacked, nothing else
update routes k set
  ice_grade_num   = coalesce(k.ice_grade_num,   c.ice_grade_num),
  mixed_grade_num = coalesce(k.mixed_grade_num, c.mixed_grade_num),
  aid_grade_num   = coalesce(k.aid_grade_num,   c.aid_grade_num)
from m_dup d join routes c on c.id = d.copy
where k.id = d.keep and k.area_id = d.keep_area;

-- 2. the copy of a climb the keeper holds is deleted — only while that keeper is still there
delete from routes r using m_dup d
 where r.id = d.copy
   and exists (select 1 from routes k where k.id = d.keep and k.area_id = d.keep_area);

-- 3. every other route on the copy moves into the keeper area
update routes r set area_id = m.to_area from m_move m where r.id = m.id and r.area_id = m.from_area;

-- 4. the copy areas, once empty
delete from areas a using m_copy c
 where a.id = c.id
   and not exists (select 1 from routes where area_id = a.id)
   and not exists (select 1 from areas s where s.parent_id = a.id);

-- 5. recount
update areas set route_count = (
  select count(*) from routes r join areas a2 on a2.id = r.area_id where a2.path <@ areas.path
) where id in (select id from m_recount);

commit;
